// Check if a given simulation timestamp is in the pre-launch walking phase
inline bool is_walking_phase(float t_s) {
    return (t_s < FLIGHT_LAUNCH_TIME_S);
}

// Fast O(1) monotonic cursor-based lookup and linear interpolation on ESP32
inline bool combined_sim_get_sample(float t_s, CombinedSimDataPoint &out) {
    static uint16_t cursor = 0;
    if (COMBINED_SIM_COUNT == 0) return false;

    if (t_s <= COMBINED_SIM_DATA[0].time_s) {
        out = COMBINED_SIM_DATA[0];
        return true;
    }

    if (t_s >= COMBINED_SIM_DATA[COMBINED_SIM_COUNT - 1].time_s) {
        out = COMBINED_SIM_DATA[COMBINED_SIM_COUNT - 1];
        return false; // Reached end of simulation
    }

    while (cursor + 1 < COMBINED_SIM_COUNT && COMBINED_SIM_DATA[cursor + 1].time_s <= t_s) {
        cursor++;
    }
    while (cursor > 0 && COMBINED_SIM_DATA[cursor].time_s > t_s) {
        cursor--;
    }

    const CombinedSimDataPoint &p0 = COMBINED_SIM_DATA[cursor];
    const CombinedSimDataPoint &p1 = COMBINED_SIM_DATA[cursor + 1];
    float dt = p1.time_s - p0.time_s;
    float factor = (dt > 1e-6f) ? ((t_s - p0.time_s) / dt) : 0.0f;
    if (factor < 0.0f) factor = 0.0f;
    if (factor > 1.0f) factor = 1.0f;

    out.time_s      = t_s;
    out.ax          = p0.ax + factor * (p1.ax - p0.ax);
    out.ay          = p0.ay + factor * (p1.ay - p0.ay);
    out.az          = p0.az + factor * (p1.az - p0.az);
    out.gx          = p0.gx + factor * (p1.gx - p0.gx);
    out.gy          = p0.gy + factor * (p1.gy - p0.gy);
    out.gz          = p0.gz + factor * (p1.gz - p0.gz);
    out.pressure_pa = p0.pressure_pa + factor * (p1.pressure_pa - p0.pressure_pa);
    out.vert_accel  = p0.vert_accel + factor * (p1.vert_accel - p0.vert_accel);
    out.lat_accel   = p0.lat_accel + factor * (p1.lat_accel - p0.lat_accel);
    out.is_flight   = (factor >= 0.5f) ? p1.is_flight : p0.is_flight;
    return true;
}

